/** Ids that are seamless loops (play with AudioEngine.loop). */
export const LOOP_IDS: SoundId[] = ['board_slide_loop', 'dung_roll_loop', 'night_loop', 'saloon_loop', 'storm_loop', 'swarm_loop', 'underworld_loop', 'water_loop', 'wind_loop'];

export interface InstrumentSample {
  note: string;
  midi: number;
  /** velocity layer (1 soft .. 3 hard) */
  vel: number;
  /** relative to the audio base path */
  file: string;
}

